/* Bauhaus — primary red/blue/yellow, geometric blocks, heavy grotesk */
.theme-bauhaus {
  --bg: oklch(0.95 0.012 85);
  --surface: oklch(0.99 0.005 85);
  --surface-2: oklch(0.9 0.02 85);
  --fg: oklch(0.16 0.01 60);
  --fg-muted: oklch(0.44 0.015 60);
  --accent: oklch(0.55 0.23 28);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.45 0.2 262);
  --line: oklch(0.16 0.01 60);
  --success: oklch(0.6 0.16 150);
  --warning: oklch(0.83 0.18 88);
  --danger: oklch(0.55 0.2 27);

  --radius: 0rem;
  --radius-sm: 0rem;
  --radius-lg: 0rem;
  --radius-pill: 9999px;

  --shadow-1: 0 0 0 2px var(--fg);
  --shadow-2: 8px 8px 0 0 oklch(0.45 0.2 262);
  --shadow-3: 14px 14px 0 0 oklch(0.83 0.18 88);
  --glow: 0 0 0 4px oklch(0.83 0.18 88);

  --border-width: 2px;
  --blur-amount: 0px;

  --font-display: "Jost", "Futura", sans-serif;
  --font-body: "Jost", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: uppercase;
  --label-tracking: 0.18em;

  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 88% 12%, oklch(0.83 0.18 88) 0 6rem, transparent 6rem),
    linear-gradient(180deg, oklch(0.45 0.2 262 / 12%) 0 0.75rem, transparent 0.75rem);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-bauhaus h1,
.theme-bauhaus h2,
.theme-bauhaus h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
  text-transform: uppercase;
}

/* signature */
.theme-bauhaus { --font-ui: var(--font-display); }
.theme-bauhaus h1, .theme-bauhaus h2 { text-transform: uppercase; font-weight: 700; }
.theme-bauhaus h2::before { content: ""; display: inline-block; width: 0.5em; height: 0.5em; background: var(--accent); margin-right: 0.4em; }
.theme-bauhaus button { text-transform: uppercase; letter-spacing: 0.06em; }

/* depth */
.theme-bauhaus thead th { text-transform: uppercase; letter-spacing: var(--label-tracking); font-size: 0.7em; border-bottom: 3px solid var(--fg); text-align: left; }
.theme-bauhaus tbody tr { border-bottom: 2px solid oklch(0.16 0.01 60 / 12%); }
.theme-bauhaus tbody tr:hover { background: oklch(0.83 0.18 88 / 18%); }
.theme-bauhaus input, .theme-bauhaus select, .theme-bauhaus textarea { border: 2px solid var(--fg); border-radius: 0; background: var(--surface); }
.theme-bauhaus input:focus, .theme-bauhaus select:focus, .theme-bauhaus textarea:focus { outline: none; box-shadow: 4px 4px 0 0 oklch(0.45 0.2 262); border-color: var(--fg); }
.theme-bauhaus a { color: oklch(0.45 0.2 262); text-decoration-thickness: 3px; text-underline-offset: 3px; }
.theme-bauhaus a:hover { background: oklch(0.83 0.18 88); color: var(--fg); text-decoration-color: var(--fg); }
.theme-bauhaus kbd { font-family: var(--font-mono); font-size: 0.85em; padding: 0.1em 0.45em; border: 2px solid var(--fg); border-radius: 0; background: var(--surface); box-shadow: 2px 2px 0 0 var(--fg); }
.theme-bauhaus ::selection { background: oklch(0.45 0.2 262); color: oklch(0.99 0 0); }
.theme-bauhaus ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-bauhaus ::-webkit-scrollbar-track { background: oklch(0.83 0.18 88); }
.theme-bauhaus ::-webkit-scrollbar-thumb { background: var(--fg); border-radius: 0; border: 2px solid oklch(0.83 0.18 88); }
.theme-bauhaus .label-caps { font-weight: 700; }
.theme-bauhaus .themed-border { border: 2px solid var(--fg); box-shadow: 6px 6px 0 0 var(--accent); }
/* physical: hard-shadow press — the block lands on the page */
.theme-bauhaus button { box-shadow: 4px 4px 0 0 var(--fg); }
.theme-bauhaus button:active { transform: translate(4px, 4px); box-shadow: none; transition: none; }

/* alt mode: night workshop — primaries stay primary on near-black */
.theme-bauhaus.alt-mode {
  --bg: oklch(0.145 0.012 85.0);
  --surface: oklch(0.185 0.012 85.0);
  --surface-2: oklch(0.225 0.012 85.0);
  --fg: oklch(0.97 0.005 90);
  --fg-muted: oklch(0.70 0.01 90);
  --line: oklch(0.95 0.01 85);
  --accent: oklch(0.6 0.23 28);
  --accent-2: oklch(0.55 0.19 262);
  --shadow-1: 0 0 0 2px var(--fg);
  --shadow-2: 8px 8px 0 0 oklch(0.55 0.19 262);
  --shadow-3: 14px 14px 0 0 oklch(0.83 0.18 88);
  background-image: radial-gradient(circle at 88% 12%, oklch(0.83 0.18 88 / 25%) 0 6rem, transparent 6rem);
  background-attachment: fixed;
}
.theme-bauhaus.alt-mode thead th, .theme-bauhaus.alt-mode input, .theme-bauhaus.alt-mode select, .theme-bauhaus.alt-mode textarea, .theme-bauhaus.alt-mode kbd, .theme-bauhaus.alt-mode .themed-border { border-color: var(--fg); }
.theme-bauhaus.alt-mode tbody tr { border-bottom-color: oklch(0.95 0.01 85 / 18%); }
.theme-bauhaus.alt-mode a { color: oklch(0.72 0.14 262); }
.theme-bauhaus.alt-mode a:hover { background: oklch(0.83 0.18 88); color: oklch(0.16 0.01 60); text-decoration-color: oklch(0.16 0.01 60); }
.theme-bauhaus.alt-mode button { box-shadow: 4px 4px 0 0 oklch(0.83 0.18 88); }
.theme-bauhaus.alt-mode button:active { box-shadow: none; }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
